<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Folder,Search} from '@element-plus/icons-vue'
import {service} from '@/services/service'
import type {ExtractionTemplate,TemplateFolder} from '@/domain/types'
import {cloneDraft,safeFilename} from '@/domain/validation'
import FieldEditor from '@/components/FieldEditor.vue'
const templates=ref<ExtractionTemplate[]>([]),folders=ref<TemplateFolder[]>([]),folder=ref(''),query=ref(''),page=ref(1),loading=ref(false),error=ref(''),editing=ref(false),viewing=ref<ExtractionTemplate|null>(null),saving=ref(false)
const current=ref<ExtractionTemplate>({id:'',name:'',description:'',scope:'personal',folderId:'',fields:[]})
const tree=computed(()=>{const make=(scope:'system'|'personal',parent?:string):any[]=>folders.value.filter(f=>f.scope===scope&&(f.parentId||undefined)===parent).map(f=>({id:f.id,label:f.name,children:make(scope,f.id)}));return[{id:'@system',label:'系统模板',children:make('system')},{id:'@personal',label:'个人模板',children:make('personal')}]})
const visible=computed(()=>templates.value.filter(t=>(!folder.value||(folder.value==='@system'?t.scope==='system':folder.value==='@personal'?t.scope==='personal':t.folderId===folder.value))&&(!query.value||`${t.name} ${t.description}`.includes(query.value.trim()))))
const paged=computed(()=>visible.value.slice((page.value-1)*15,page.value*15))
const selectedFolder=computed(()=>folders.value.find(f=>f.id===folder.value))
async function load(){loading.value=true;try{[templates.value,folders.value]=await Promise.all([service.listTemplates(),service.listTemplateFolders()]);error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function edit(t?:ExtractionTemplate,copy=false){current.value=t?cloneDraft(t):{id:'',name:'',description:'',scope:'personal',folderId:selectedFolder.value?.scope==='personal'?selectedFolder.value.id:folders.value.find(f=>f.scope==='personal')?.id||'',fields:[]};if(copy){current.value.id='';current.value.name+=' · 副本';current.value.scope='personal';current.value.folderId=folders.value.find(f=>f.scope==='personal')?.id||''}editing.value=true}
async function save(){const t=current.value;if(!t.name.trim()||!t.folderId||!t.fields.length||t.fields.some(f=>!f.name.trim())){ElMessage.warning('请填写模板名称、所属目录和至少一个有效字段');return}if(new Set(t.fields.map(f=>f.name.trim())).size!==t.fields.length){ElMessage.warning('字段名称不能重复');return}saving.value=true;try{await service.saveTemplate(cloneDraft(t));editing.value=false;await load();ElMessage.success('模板已保存')}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function remove(t:ExtractionTemplate){try{await ElMessageBox.confirm(`删除个人模板「${t.name}」？历史分析结果不受影响。`,'删除模板',{confirmButtonText:'删除',cancelButtonText:'取消'});await service.deleteTemplate(t.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
function download(t:ExtractionTemplate){const blob=new Blob([JSON.stringify({version:1,name:t.name,description:t.description,fields:t.fields.map(({name,description})=>({name,description}))},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=safeFilename(t.name)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function importTemplate(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('模板文件不能超过 2 MB');const data=JSON.parse(await file.text());if(typeof data.name!=='string'||!Array.isArray(data.fields)||data.fields.some((f:any)=>typeof f.name!=='string'))throw Error('模板格式不正确，需要模板名称和字段列表');edit();current.value.name=data.name;current.value.description=String(data.description||'');current.value.fields=data.fields.map((f:any)=>({id:crypto.randomUUID(),name:f.name,description:String(f.description||'')}))}catch(e){ElMessage.error((e as Error).message)}finally{input.value=''}}
async function manageFolder(action:'create'|'rename'|'delete'){try{if(action==='delete'){if(!selectedFolder.value)return;await ElMessageBox.confirm(`删除目录「${selectedFolder.value.name}」？请先移出目录内的模板。`,'删除目录',{confirmButtonText:'删除',cancelButtonText:'取消'});await service.deleteTemplateFolder(selectedFolder.value.id);folder.value='@personal'}else{const {value}=await ElMessageBox.prompt('填写目录名称',action==='create'?'新建个人模板目录':'重命名目录',{inputValue:action==='rename'?selectedFolder.value?.name:'',inputValidator:v=>!!v.trim()||'请填写名称'});await service.saveTemplateFolder({id:action==='rename'?selectedFolder.value!.id:'',name:value.trim(),scope:'personal',parentId:action==='create'&&selectedFolder.value?.scope==='personal'?selectedFolder.value.id:selectedFolder.value?.parentId})}await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
onMounted(load)
</script>
<template>
 <div class="template-page"><header class="page-heading"><h1>提取模板</h1><div class="actions"><label class="import-template">导入模板<input type="file" accept=".json" @change="importTemplate" aria-label="导入模板"/></label><el-button type="primary" :icon="Plus" @click="edit()">新增模板</el-button></div></header><div class="template-layout">
  <aside class="panel template-sidebar"><div class="category-heading"><h2>模板分类</h2><el-button v-if="service.capabilities.templateFolders" :icon="Plus" text aria-label="新建个人模板目录" @click="manageFolder('create')"/></div><el-tree :data="tree" node-key="id" default-expand-all highlight-current @node-click="(node:any)=>{folder=node.id;page=1}"><template #default="{data}"><span class="folder-node"><el-icon><Folder/></el-icon>{{data.label}}</span></template></el-tree><div class="folder-actions" v-if="selectedFolder?.scope==='personal'&&service.capabilities.templateFolders"><el-button text @click="manageFolder('rename')">重命名</el-button><el-button text @click="manageFolder('delete')">删除目录</el-button></div></aside>
  <section class="panel template-list" v-loading="loading"><div class="toolbar template-toolbar"><el-input v-model="query" clearable :prefix-icon="Search" placeholder="查找模板名称或描述" @input="page=1" style="max-width:360px"/><span class="muted">共 <strong class="number">{{visible.length}}</strong> 个模板</span></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button><el-table :data="paged" class="template-table"><el-table-column prop="name" label="模板名称" min-width="200"/><el-table-column prop="description" label="提取内容" min-width="240" show-overflow-tooltip/><el-table-column label="字段数" width="100"><template #default="{row}"><strong class="number">{{row.fields.length}}</strong></template></el-table-column><el-table-column label="操作" min-width="340"><template #default="{row}"><div class="template-actions"><el-button link type="primary" @click="viewing=row">查看字段</el-button><el-button v-if="row.scope==='personal'" link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" @click="edit(row,true)">复制模板</el-button><el-button link type="primary" @click="download(row)">导出配置</el-button><el-button v-if="row.scope==='personal'" link type="danger" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table><div class="template-pagination"><el-pagination v-model:current-page="page" :page-size="15" :total="visible.length" layout="total,prev,pager,next"/></div></section>
 </div><el-dialog v-model="editing" :title="current.id?'编辑提取模板':'新增提取模板'" width="900px" :close-on-click-modal="false"><div class="template-form"><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="current.name" maxlength="100"/></el-form-item><el-form-item label="所属目录" required><el-select v-model="current.folderId" style="width:100%"><el-option v-for="f in folders.filter(f=>f.scope==='personal')" :key="f.id" :label="f.name" :value="f.id"/></el-select></el-form-item><el-form-item label="模板描述"><el-input v-model="current.description" type="textarea" :rows="2"/></el-form-item></el-form><FieldEditor v-model="current.fields"/></div><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存模板</el-button></template></el-dialog><el-dialog :model-value="!!viewing" @update:model-value="viewing=null" :title="viewing?.name+' · 提取字段'" width="850px"><el-table :data="viewing?.fields" max-height="500"><el-table-column type="index" label="序号" width="70"/><el-table-column prop="name" label="字段名称" min-width="180"/><el-table-column prop="description" label="提取说明" min-width="320"/></el-table><template #footer><el-button @click="viewing=null">关闭</el-button></template></el-dialog></div>
</template>
<style scoped>.template-page{height:100%;display:flex;flex-direction:column}.template-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px;padding:16px;flex:1;min-height:0}.template-sidebar{padding:16px;overflow:auto}.category-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.category-heading h2{font-size:16px}.folder-node{display:flex;align-items:center;gap:8px}.template-sidebar :deep(.el-tree-node__content){height:42px}.template-list{display:flex;flex-direction:column;min-height:0;overflow:auto}.template-toolbar{padding:16px}.template-table{flex:1}.template-actions{display:flex;gap:12px;flex-wrap:wrap}.template-pagination{padding:18px;display:flex;justify-content:flex-end}.import-template{position:relative;border:1px solid #dce3ed;border-radius:7px;padding:5px 14px;font-size:14px;background:white}.import-template input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.template-form{max-height:65dvh;overflow:auto;padding-right:6px}.folder-actions{margin-top:16px;display:flex}.template-form :deep(.field-item){background:#fafbfd}@media(max-width:760px){.template-layout{grid-template-columns:1fr;grid-template-rows:170px minmax(0,1fr);padding:8px;gap:8px}.template-sidebar{padding:10px}.category-heading{margin:0}.template-toolbar{padding:10px}}</style>
